package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.t = c.t.Add(d)
}

func TestNewLimiter_Validation(t *testing.T) {
	fc := &fakeClock{t: time.Now()}
	tests := []struct {
		name     string
		capacity float64
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"valid", 10, 1, fc, false},
		{"zero capacity", 0, 1, fc, true},
		{"negative capacity", -1, 1, fc, true},
		{"zero rate", 10, 0, fc, true},
		{"negative rate", 10, -1, fc, true},
		{"nil clock", 10, 1, nil, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := NewLimiter(tt.capacity, tt.rate, tt.clock)
			if (err != nil) != tt.wantErr {
				t.Fatalf("err = %v, wantErr = %v", err, tt.wantErr)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)
	tests := []struct {
		name     string
		capacity float64
		rate     float64
		advances []time.Duration
		n        int
		want     []bool
	}{
		{
			name:     "burst then deny",
			capacity: 5,
			rate:     1,
			advances: []time.Duration{0, 0, 0, 0, 0, 0},
			n:        1,
			want:     []bool{true, true, true, true, true, false},
		},
		{
			name:     "refill after wait",
			capacity: 3,
			rate:     1,
			advances: []time.Duration{0, 0, 0, 0, 2 * time.Second, 0},
			n:        1,
			want:     []bool{true, true, true, false, true, true},
		},
		{
			name:     "allowN burst",
			capacity: 10,
			rate:     2,
			advances: []time.Duration{0, 0, 3 * time.Second, 0},
			n:        4,
			want:     []bool{true, true, true, false},
		},
		{
			name:     "n zero always allowed",
			capacity: 1,
			rate:     1,
			advances: []time.Duration{0, 0},
			n:        0,
			want:     []bool{true, true},
		},
		{
			name:     "n negative always allowed",
			capacity: 1,
			rate:     1,
			advances: []time.Duration{0},
			n:        -1,
			want:     []bool{true},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			fc := &fakeClock{t: base}
			l, err := NewLimiter(tt.capacity, tt.rate, fc)
			if err != nil {
				t.Fatal(err)
			}
			for i, want := range tt.want {
				if i > 0 {
					fc.Advance(tt.advances[i])
				}
				if got := l.AllowN(tt.n); got != want {
					t.Fatalf("call %d: got %v, want %v", i, got, want)
				}
			}
		})
	}
}

func TestConcurrent(t *testing.T) {
	fc := &fakeClock{t: time.Now()}
	l, _ := NewLimiter(100, 100, fc)
	var wg sync.WaitGroup
	var allowed int64
	var mu sync.Mutex
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.AllowN(1) {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed > 100 {
		t.Fatalf("allowed %d, expected <= 100", allowed)
	}
}
